import six
from .exceptions import DeviceCharacteristicsIsEmpty


class DeviceCharacteristics:
    """Object for encapsulating all parameters needed for device creation."""
    def __init__(self, domain_capabilities=None):
        """
        :param domain_capabilities: LTE capabilities requirement
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.DeviceCharacteristicsIsEmpty`: If all params are None
        """
        # (FUTURE) add logging for debugging
        # logger.info('DeviceCharacteristics raw parameters:\n   domain_capabilities: {}, abilities: {}, possible_cells: {}'.format(
        #     domain_capabilities, abilities, possible_cells))
        # TODO check that at least one param is given
        self.domain_capabilities = domain_capabilities
        self._ensure_not_empty()

    def _ensure_not_empty(self):
        if self._is_empty():
            raise DeviceCharacteristicsIsEmpty(self)

    def ensure_not_empty(self):
        """
        Ensure if domain_capabilities is not empty
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.DeviceCharacteristicsIsEmpty`: If all params are None
        """
        if self._is_empty():
            raise DeviceCharacteristicsIsEmpty(self)

    def _is_empty(self):
        empty = self.domain_capabilities is None
        return empty

    def __eq__(self, other):
        return vars(self) == vars(other)

    def __str__(self):
        domain_capabilities_str = self.domain_capabilities
        if isinstance(self.domain_capabilities, six.string_types):
            domain_capabilities_str = f"'{self.domain_capabilities}'"
        return f"{self.__class__.__name__}(domain_capabilities={domain_capabilities_str})"

    def __repr__(self):
        return self.__str__()
